import os

from langchain.agents import create_agent
from langchain_core.tools import tool

@tool
def search_delivery_policy(topic: str) -> str:
    """Search the synthetic public delivery policy."""

    policies = {
        "delay": (
            "Delivery delays exceeding 48 hours "
            "qualify for support review."
        )
    }

    return policies.get(
        topic.lower(),
        "No matching policy found."
    )

agent = create_agent(
    model=os.environ["AGENT_MODEL"],
    tools=[search_delivery_policy],
    system_prompt=(
        "You are a delivery support assistant. "
        "Use verified policy evidence."
    )
)

result = agent.invoke(
    {
        "messages": [
            {
                "role": "user",
                "content": (
                    "What happens when delivery "
                    "is delayed?"
                )
            }
        ]
    },
    config={"recursion_limit": 12}
)

print(result["messages"][-1].content)

